-- Produktkatalogen från supabase/katalog/liggunderlag.csv, supabase/katalog/ryggsackar.csv, supabase/katalog/sovsackar.csv, supabase/katalog/talt-och-vindskydd.csv.
-- Skapad med "npm run katalog". Ändra inte filen för hand: ändra CSV:n och skapa en ny migrering.

on conflict (lower(marke), lower(modell), lower(coalesce(version, ''))) do update set
  kategori = excluded.kategori,
  underkategori = excluded.underkategori,
  packvikt_g = excluded.packvikt_g,
  minvikt_g = excluded.minvikt_g,
  pris_sek_ca = excluded.pris_sek_ca,
  ean = excluded.ean,
  kalla = excluded.kalla,
  kontrollerad = excluded.kontrollerad,
  egenskaper = excluded.egenskaper;
